<script setup lang="ts">
import {ref,computed} from 'vue';
import {api,message} from '../api';
import {label,date,ton,download,eventLabel} from '../fulfillment';
import ForecastPanel from './ForecastPanel.vue';
const props=defineProps<{element:any;waybill:any;includeTest:boolean}>(),emit=defineEmits(['close','asset']);const error=ref('');
const nodeAssets=computed(()=>props.waybill.assets.filter((a:any)=>props.element.taskIds?.includes(a.id)));
async function file(f:any,stage=false){try{const r=await api.get((stage?'/intermodal/attachments/':'/fulfillment/evidence/')+f.id,{responseType:'blob'});download(r.data,f.name,f.mime);}catch(e){error.value=message(e);}}
</script>
<template><section class="element-popup" role="dialog" :aria-label="element.id.startsWith('node:')||element.id.startsWith('endpoint:')?'节点运输进度':'运输要素详情'"><header><div><small>{{element.isPort?'港口':element.mode?label(element.mode):'交接节点'}}</small><h3>{{element.title||element.destination}}</h3></div><button class="popup-close" aria-label="关闭运输详情" @click="emit('close')">×</button></header><div class="popup-scroll"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="popup-waybill"><b>{{waybill.waybillNo}}</b><span>{{waybill.shipper}}</span><span>{{waybill.cargo}} · {{ton(waybill.quantityKg)}}</span></div><template v-if="element.taskIds"><div v-if="element.isPort" class="port-ledger"><div><small>单据确认集港量</small><strong>{{ton(element.collectedKg)}}</strong><span>/ {{ton(element.targetKg)}}</span></div><div v-if="element.awaitingEvidenceKg"><small>回传数量待核对</small><strong>{{ton(element.awaitingEvidenceKg)}}</strong><span>尚未计入集港实收</span></div><div><small>已发船量</small><strong>{{ton(element.shippedKg)}}</strong><span>{{element.allShipped?"全部发运":"分批发运中"}}</span></div><p>集港实收以司机回传的箱重、过磅净重及单据为准；计划载量不参与累计。</p></div><div v-else class="node-progress"><strong>{{ton(element.mode==='ROAD'?element.arrivedKg:element.shippedKg)}} <small>/ {{ton(element.targetKg)}}</small></strong><el-progress :percentage="element.percent" :stroke-width="7"/><p>{{element.mode==='ROAD'?'已集运到达':'已发运'}} · {{element.allArrived?'全部到达':element.allShipped?'全部发运':'分批运输中'}}</p><small v-if="element.unverifiedTasks">{{element.unverifiedTasks}} 项回传缺少数量依据，待核对</small><p v-for="w in element.warnings" :key="w" class="popup-warning">{{w}}</p></div><dl><dt>起点</dt><dd>{{element.origin}}</dd><dt>交接地点</dt><dd>{{element.destination}}</dd><dt>运输任务</dt><dd>{{element.taskIds.length}} 项</dd></dl><div v-if="element.boxes?.length"><h4>已到达集装箱</h4><p v-for="b in element.boxes" :key="b.boxNo">{{b.boxNo}} · {{ton(b.quantityKg)}}</p></div><div v-if="element.tickets?.length"><h4>过磅数量依据</h4><p v-for="t in element.tickets" :key="t.ticketNo">{{t.ticketNo}} · 净重 {{ton(t.quantityKg)}}</p></div><section v-if="nodeAssets.length" class="node-assets"><h4>关联运输与预测</h4><button v-for="a in nodeAssets" :key="a.id" @click="emit('asset',a)">{{a.title}} · {{label(a.status)}}<small>{{a.eta?'预计到达 '+date(a.eta):'点击查看预测依据'}}{{a.alerts.length?' · '+a.alerts.length+' 项预警':''}}</small></button></section></template><template v-else-if="element.stage"><div class="popup-status"><el-tag size="small">{{label(element.status)}}</el-tag></div><dl><dt>{{element.mode==='ROAD'?'过磅回传':'运输数量'}}</dt><dd>{{element.mode==='ROAD'?(element.feedbackSubmittedAt||element.feedback?.quantityKg?ton(element.unloadedKg||element.feedback?.quantityKg):'待回传磅单'):ton(element.quantityKg)}}</dd><dt>发运 / 到达</dt><dd>{{element.stage.origin}} → {{element.stage.destination}}</dd><template v-if="element.mode==='ROAD'"><dt>司机</dt><dd>{{element.driver||'尚未分配'}}</dd><dt>装载</dt><dd>{{element.stage.containerized?'集装箱':'散货'}}</dd><template v-if="element.movement"><dt>行驶路线</dt><dd>{{element.movement.routeName}}</dd></template></template><template v-if="element.mode==='WATER'"><dt>航次</dt><dd>{{element.voyage}}</dd><dt>MMSI</dt><dd>{{element.mmsi||'尚未关联'}}</dd><dt>提单号</dt><dd>{{element.stage.billOfLading}}</dd><dt>本船发运</dt><dd>{{element.loadedKg?ton(element.loadedKg):'待回传'}}</dd><dt>箱号</dt><dd>{{element.stage.boxes?.join('、')||'散货'}}</dd></template><template v-if="element.mode==='RAIL'"><dt>铁路运单号</dt><dd>{{element.stage.railWaybillNo}}</dd><dt>最近回传节点</dt><dd>{{element.currentNode?.nodeName||'等待节点反馈'}}</dd></template><dt>计划开始</dt><dd>{{date(element.plannedDepartureAt)}}</dd><dt>预计结束</dt><dd>{{date(element.plannedArrivalAt)}}</dd><template v-if="element.position"><dt>{{element.replayAt?"回放坐标":element.position?.dataQuality==='INITIALIZATION'?"参考坐标":"当前坐标"}}</dt><dd>{{element.position.longitude.toFixed(5)}}，{{element.position.latitude.toFixed(5)}}</dd></template><dt>位置来源</dt><dd>{{element.position?.sourceSystem==='BUSINESS_INITIALIZATION'?'业务初始化记录':element.position?.sourceSystem||'暂无定位'}}<small v-if="element.position">{{date(element.position.observedAt)}}</small></dd></dl><section v-if="element.alerts?.length" class="popup-alerts"><h4>当前预警 · {{element.alerts.length}}</h4><p v-for="a in element.alerts" :key="a.id||a.type"><b>{{a.level==='HIGH'?'高风险':'需关注'}}</b> {{a.message}}</p></section><p v-if="element.replayAt" class="playback-note">历史轨迹回放：{{date(element.replayAt)}}。运输状态、单据和预测展示当前业务记录。</p><ForecastPanel :task-id="element.id" :include-test="includeTest" :preview="element.previewForecast"/><details v-if="element.timeline?.length"><summary>运输过程 · {{element.timeline.length}} 项</summary><p v-for="e in element.timeline" :key="e.id">{{date(e.at)}} · {{e.nodeName||eventLabel(e.type)}}</p></details><details v-if="element.feedback?.containers?.length"><summary>司机回传箱号与数量</summary><p v-for="b in element.feedback.containers" :key="b.boxNo">{{b.boxNo}} · {{ton(b.quantityKg)}}</p></details><div v-if="element.evidence?.length||element.stage.attachments?.length"><h4>运输凭证</h4><el-button v-for="f in element.evidence" :key="f.id" link type="primary" @click="file(f)">{{f.name}}</el-button><el-button v-for="f in element.stage.attachments" :key="f.id" link type="primary" @click="file(f,true)">{{f.name}}</el-button></div></template><template v-else><p>{{element.origin}} → {{element.destination}}</p><p>计划运输节点</p></template><router-link :to="'/services?businessId='+waybill.id" class="popup-service-link">查看联运服务 →</router-link></div></section></template>
<style scoped>.port-ledger{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:12px;background:#f1f8f5;border-radius:7px}.port-ledger small,.port-ledger span{display:block;font-size:10px;color:#83988b}.port-ledger strong{display:block;font-size:20px;color:#27815b;margin:5px 0}.port-ledger p{grid-column:1 / -1;font-size:10px;color:#7a8d82}.playback-note{color:#9b7a46;font-size:10px;padding:8px;background:#fff8ed;border-radius:5px}.node-assets button{display:block;text-align:left;width:100%;border:1px solid #e9edf3;background:#f8fafc;padding:9px 10px;margin:8px 0;border-radius:6px;color:#486078;font-size:11px;cursor:pointer}.node-assets button small{display:block;color:#8795a5;margin-top:4px}.element-popup{width:360px;background:#fff;border:1px solid #dde5ed;border-radius:10px;box-shadow:0 8px 32px #24395030;color:#283b50;font-family:inherit}.element-popup>header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #edf0f4}.element-popup h3{font-size:15px;margin:5px 0 0}.element-popup header small{font-size:11px;color:#7a8897}.popup-close{border:0;background:#f3f5f8;border-radius:5px;width:26px;height:26px;font-size:20px;color:#798698;cursor:pointer}.popup-scroll{padding:16px 18px;max-height:min(420px,55vh);overflow:auto;overscroll-behavior:contain;font-size:12px;line-height:1.6}.popup-waybill{display:grid;gap:4px;padding-bottom:12px;color:#7a899a}.popup-waybill b{color:#344a62;font-size:12px}.popup-status{display:flex;gap:8px;margin:4px 0 12px}.element-popup dl{display:grid;grid-template-columns:76px 1fr;gap:8px;margin:12px 0}.element-popup dt{color:#8190a1}.element-popup dd{margin:0;overflow-wrap:anywhere}.element-popup dd small{display:block;color:#8692a0}.popup-alerts{background:#fff4ee;border:1px solid #ffe2d6;border-radius:7px;padding:10px 12px;color:#aa5131}.element-popup h4{font-size:12px;margin:6px 0}.element-popup p{margin:6px 0}.node-progress strong{font-size:22px}.node-progress strong small{font-size:12px;font-weight:400;color:#8a97a6}.node-progress>.el-progress{margin-top:10px}.node-progress>small{color:#be7943}.popup-service-link{display:block;margin-top:16px;color:#df2b35;font-size:12px}.popup-warning{color:#bd6741}details{margin:14px 0}summary{cursor:pointer;font-weight:600}@media(max-width:500px){.element-popup{width:280px}}</style>

